import{_ as a,d as t,e as i,x as n}from"./chunks/framework.BRr8VP3a.js";const h=JSON.parse('{"title":"D.22 Class, Identity, Inequality, and Social Exclusion","description":"","frontmatter":{"title":"D.22 Class, Identity, Inequality, and Social Exclusion","xkChars":0,"xkWords":438},"headers":[],"relativePath":"en/theory/appendix-d/d-22.md","filePath":"en/theory/appendix-d/d-22.md"}'),s={name:"en/theory/appendix-d/d-22.md"};function o(r,e,c,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<div class="theory-source"><h1 id="section-d-22" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.22</span><span class="xk-num__gap"></span></span>Class, Identity, Inequality, and Social Exclusion <a class="header-anchor" href="#section-d-22" aria-label="Permalink to &quot;D.22 Class, Identity, Inequality, and Social Exclusion {#section-d-22}&quot;">​</a></h1><p>In the main text, see §2.5, §5.5.1, §9.7, §10.5–10.8, and §14.4–14.5. Research entries cover 22.01–22.08.</p><p>Income, wealth, cash buffers, control over production and management, qualifications, social ties, and standing through recognition are distinct resources. Research on class and strata, stigma and social boundaries, intersectionality, elite reproduction, colonialism and labor, poverty, and mobility points to different possible channels. An identity category alone cannot determine an individual’s circumstances.</p><p>Naming a group does not establish a common will. Naming can have real effects through classification, service eligibility, employment, and interaction. Intersectionality calls for examining how several sets of rules jointly exclude a particular position, in addition to overlap among circles or the number of identities. Statistical interactions, intersections among institutions, and lived experience require separate arguments. An improvement in a group average can coexist with continuing exclusion within the group.</p><p>Analysis of education and social mobility must distinguish birth cohort, enrollment applications, admission, graduation, and subsequent opportunities. Measured differences in skill do not establish fairness in opportunities to learn. The success of a few people does not represent the openness of the institution as a whole. Conversely, barriers to entry do not erase the value of actual skills. To establish elite control, trace access, agendas, resources, and mechanisms for removal. Educational credentials or occupations alone do not establish it.</p><p>In a teaching example, a benefit raises an area’s average income, but people without identity documents are excluded from the statistics and the application process. The average result can remain valid. Claims about coverage must be narrowed, and people who did not enter the process must be listed separately. The time, transport, care, and evidence-gathering costs that poverty brings should be recorded as concrete constraints. They must not become definitive judgments about capability or character. Recognition, redistribution, and participation rights each raise distinct questions.</p><p>Resources become opportunities for individuals through conditions of time, use, control, and implementation. Household totals, business assets, or group averages can answer aggregate questions. They cannot directly assign control and welfare to individuals. An identity label can have effects only through a channel by which it actually reaches an employer, service rule, or interaction. A label used only by researchers does not automatically activate those consequences. Relative gaps can shrink while absolute gaps widen. State the comparison objectives separately.</p><p>Research topics. 22.01 Class, strata, and the distribution of capital. 22.02 Standing, stigma, and social boundaries. 22.03 Gender, race, ethnicity, and intersectionality. 22.04 Elites, oligarchies, and reproduction of power. 22.05 Colonialism, slavery, and racialized labor. 22.06 Poverty, deprivation, and scarcity. 22.07 Social mobility, education, and inheritance. 22.08 Recognition, redistribution, and life together.</p></div>',1)])])}const m=a(s,[["render",o]]);export{h as __pageData,m as default};
